":\"確認済み\",\"personKey\":\"name:黒のありす\",\"recordId\":\"76ff66887d359b8b2c9c\"},{\"season\":\"アズヴォルト・レヴナント 後半\",\"mode\":\"アンリミ\",\"className\":\"ネメシス\",\"rank\":89,\"name\":\"眼鏡たそ\",\"cr\":1851,\"source\":\"2026-11-05 再録（all_seasons_merged.csv）\",\"status\":\"確認済み\",\"personKey\":\"name:眼鏡たそ\",\"recordId\":\"d2be8a1752d71c3874d4\"},{\"season\":\"アズヴォルト・レヴナント 後半\",\"mode\":\"アンリミ\",\"className\":\"ネメシス\",\"rank\":89,\"name\":\"観葉植物\",\"cr\":1851,\"source\":\"2026-11-05 再録（all_seasons_merged.csv）\",\"status\":\"確認済み\",\"personKey\":\"name:観葉植物\",\"recordId\":\"1a16948553ca55da45ec\"},{\"season\":\"アズヴォルト・レヴナント 後半\",\"mode\":\"アンリミ\",\"className\":\"ネメシス\",\"rank\":89,\"name\":\"feketerigo\",\"cr\":1851,\"source\":\"2026-11-05 再録（all_seasons_merged.csv）\",\"status\":\"確認済み\",\"personKey\":\"name:feketerigo\",\"recordId\":\"316f83c727cab42279cc\"},{\"season\":\"アズヴォルト・レヴナント 後半\",\"mode\":\"アンリミ\",\"className\":\"ネメシス\",\"rank\":97,\"name\":\"Hearthstone\",\"cr\":1850,\"source\":\"2026-11-05 再録（all_seasons_merged.csv）\",\"status\":\"確認済み\",\"personKey\":\"name:Hearthstone\",\"recordId\":\"a7b4dda999d369fa1fa1\"},{\"season\":\"アズヴォルト・レヴナント 後半\",\"mode\":\"アンリミ\",\"className\":\"ネメシス\",\"rank\":97,\"name\":\"ハル\",\"cr\":1850,\"source\":\"2026-11-05 再録（all_seasons_merged.csv）\",\"status\":\"確認済み\",\"personKey\":\"name:ハル\",\"recordId\":\"d49425d53bf96d5b9489\"}];\nconst SEASON_ORDER=[\"神殺し・アナテマ 前半\", \"神殺し・アナテマ 後半\", \"クロニクル・オブ・デスティニー 前半\", \"クロニクル・オブ・デスティニー 後半\", \"アズヴォルト・レヴナント 前半\", \"アズヴォルト・レヴナント 後半\"];\nconst SUSPECT=[\"Sadtopia\", \"H\", \"り\", \"?\", \"ま\", \"ぷ\", \"Y\", \"h\", \"よ\", \"∀\"];\nconst CLASS_ORDER=['エルフ','ロイヤル','ウィッチ','ドラゴン','ナイトメア','ビショップ','ネメシス'];\nconst $=s=>document.querySelector(s);\nconst escapeHTML=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst periodOf=s=>s.endsWith('前半')?'前半':'後半';\nconst environmentOf=s=>s.slice(0,-3);\nconst norm=s=>String(s).normalize('NFKC').toLowerCase().replace(/\\s+/g,'').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));\nconst pkey=r=>r.personKey||r.name;\nconst DATA=seed;let active='';const PAGE=50;let limit=PAGE;\n\n// 選択肢をデータから作る\nconst seasonOpts=SEASON_ORDER.map((s,i)=>`<option value=\"${i}\">${escapeHTML(s.replace(\"・アナテマ\", \"\").replace(\"・オブ・デスティニー\", \"\").replace(\"・レヴナント\", \"\"))}</option>`).join('');\n$('#fromSeason').innerHTML=seasonOpts;$('#toSeason').innerHTML=seasonOpts;$('#toSeason').value=String(SEASON_ORDER.length-1);\n$('#classFilter').insertAdjacentHTML('beforeend',CLASS_ORDER.map(c=>`<option>${escapeHTML(c)}</option>`).join(''));\n$('#coverage').textContent=`対象：${SEASON_ORDER[0].replace(' ','')}から${SEASON_ORDER[SEASON_ORDER.length-1].replace(' ','')}`;\n\n// URLの状態 ⇔ 画面\nconst PARAMS={from:'fromSeason',to:'toSeason',class:'classFilter',q:'search',n:'rankThreshold',x:'crThreshold',filter:'matchFilter',sort:'sort',model:'model',avg:'averageSort'};\nfunction loadURL(){const u=new URLSearchParams(location.search);for(const[k,id]of Object.entries(PARAMS)){if(!u.has(k))continue;const el=$('#'+id),v=u.get(k);if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===v))continue;if(id==='sort'&&!['cr','count','fullCount','bestRank','classes','rankHits','crHits','bothHits'].includes(v))continue;if(id==='model'&&!['relax','inverse','log'].includes(v))continue;el.value=v}if(u.has('p'))active=u.get('p')}\nfunction saveURL(){const u=new URLSearchParams();for(const[k,id]of Object.entries(PARAMS)){const el=$('#'+id),def=el.dataset.default;if(el.value!==def&&el.value!=='')u.set(k,el.value)}if(active)u.set('p',active);const qs=u.toString();try{history.replaceState(null,'',qs?'?'+qs:location.pathname)}catch(e){}}\nfor(const id of Object.values(PARAMS))$('#'+id).dataset.default=$('#'+id).value;\n\nfunction scoped(){const from=Number($('#fromSeason').value),to=Number($('#toSeason').value),c=$('#classFilter').value;return DATA.filter(r=>{const i=SEASON_ORDER.indexOf(r.season);return i>=from&&i<=to&&(!c||r.className===c)})}\nfunction thresholds(){return {n:Math.max(1,Math.floor(Number($('#rankThreshold').value)||10)),x:Math.max(1850,Math.floor(Number($('#crThreshold').value)||1900))}}\nfunction rankHit(r,n){return Number.isInteger(r.rank)&&r.rank>0&&r.rank<=n}\nfunction fullBeyondPeriods(){const from=Number($('#fromSeason').value),to=Number($('#toSeason').value),byPlayer=new Map();for(const r of DATA){const i=SEASON_ORDER.indexOf(r.season);if(i<from||i>to)continue;const key=pkey(r);if(!byPlayer.has(key))byPlayer.set(key,new Map());const periods=byPlayer.get(key);if(!periods.has(r.season))periods.set(r.season,new Set());periods.get(r.season).add(r.className)}return new Map([...byPlayer].map(([key,periods])=>[key,SEASON_ORDER.filter(s=>periods.get(s)?.size===CLASS_ORDER.length)]))}\nfunction achievementRows(rows){const slots=new Map();for(const r of rows){const key=JSON.stringify([r.season,r.className,pkey(r)]),old=slots.get(key);if(!old||r.cr>old.cr||(r.cr===old.cr&&(r.rank||Infinity)<(old.rank||Infinity)))slots.set(key,r)}return [...slots.values()]}\nfunction summarize(rows,n,x,fullPeriods){const m=new Map();for(const r of achievementRows(rows)){const k=pkey(r);let a=m.get(k);if(!a){a={key:k,name:r.name,separated:!!r.separated,count:0,max:0,bestRank:Infinity,classes:new Set(),rankHits:0,crHits:0,bothHits:0,fullPeriods:fullPeriods.get(k)||[],rows:[],search:new Set([norm(r.name)])};m.set(k,a)}if(r.rawName)a.search.add(norm(r.rawName));const rh=rankHit(r,n),ch=r.cr>=x;a.count++;a.max=Math.max(a.max,r.cr);if(r.rank>0)a.bestRank=Math.min(a.bestRank,r.rank);a.classes.add(r.className);a.rankHits+=+rh;a.crHits+=+ch;a.bothHits+=+(rh&&ch);a.rows.push(r)}for(const r of rows){const a=m.get(pkey(r));if(a&&r.rawName)a.search.add(norm(r.rawName))}for(const a of m.values())a.rows=rows.filter(r=>pkey(r)===a.key);return [...m.values()]}\nconst rankText=v=>Number.isFinite(v)&&v>0?v+'位':'—';\nconst diff=(a,b)=>a===b?0:a<b?-1:1; // Infinityでも安全な比較\n\nfunction initSortChips(){\n for(const id of ['averageSort']){\n  const select=$('#'+id),group=$('#'+id+'Chips');\n  group.innerHTML=[...select.options].map(o=>`<button type=\"button\" class=\"sort-chip\" data-sort-value=\"${escapeHTML(o.value)}\" aria-pressed=\"false\">${escapeHTML(o.textContent)}</button>`).join('');\n  group.addEventListener('click',e=>{const b=e.target.closest('[data-sort-value]');if(!b)return;select.value=b.dataset.sortValue;render()});\n }\n}\nfunction syncSortChips(n,x){\n const labels={rankHits:`${n}位以内の回数順`,crHits:`CR${x}以上の回数順`};\n for(const id of ['averageSort'])for(const b of $('#'+id+'Chips').querySelectorAll('button')){\n  b.setAttribute('aria-pressed',String(b.dataset.sortValue===$('#'+id).value));\n  if(id==='sort'&&labels[b.dataset.sortValue])b.textContent=labels[b.dataset.sortValue];\n }\n}\nfunction render(){const rows=scoped(),{n,x}=thresholds(),q=norm($('#search').value.trim()),filter=$('#matchFilter').value,sort=$('#sort').value;\n $('#recordCount').textContent=rows.length.toLocaleString('ja-JP');$('#playerCount').textContent=new Set(rows.map(pkey)).size.toLocaleString('ja-JP');$('#topCR').textContent=rows.length?Math.max(...rows.map(r=>r.cr)):'—';\n const metrics=[['cr','最高CR',p=>p.max,p=>p.max],['count','ビヨンド数',p=>p.count,p=>p.count],['fullCount','全ビヨ',p=>p.fullPeriods.length,p=>p.fullPeriods.length],['bestRank','最高順位',p=>rankText(p.bestRank),p=>-p.bestRank],['classes','到達クラス',p=>p.classes.size,p=>p.classes.size],['rankHits',n+'位以内',p=>p.rankHits,p=>p.rankHits],['crHits','CR'+x+'+',p=>p.crHits,p=>p.crHits],['bothHits','両方達成',p=>p.bothHits,p=>p.bothHits]];\n const primary=metrics.find(m=>m[0]===sort)||metrics[0],cols=metrics;\n $('#sortbar').innerHTML=metrics.map(m=>`<button type=\"button\" class=\"chip\" data-sort=\"${m[0]}\" aria-pressed=\"${m===primary}\">${escapeHTML(m[1])}</button>`).join('');\n $('#ranking thead tr').innerHTML='<th>順位</th><th>プレイヤー</th>'+cols.map(m=>{const on=m===primary;return `<th class=\"num sortable${on?' active':''}\" aria-sort=\"${on?(sort==='bestRank'?'ascending':'descending'):'none'}\"><button type=\"button\" data-sort=\"${m[0]}\">${escapeHTML(m[1])}<span class=\"arrow\" aria-hidden=\"true\">▼</span></button></th>`}).join('')+'<th>全ビヨ達成環境</th>';\n let players=summarize(rows,n,x,fullBeyondPeriods());\n if(q)players=players.filter(p=>[...p.search].some(s=>s.includes(q)));\n if(filter==='rank')players=players.filter(p=>p.rankHits);if(filter==='cr')players=players.filter(p=>p.crHits);if(filter==='both')players=players.filter(p=>p.bothHits);\n const score=primary[3],tie=sort==='cr'?(p=>p.count):(p=>p.max);\nplayers.sort((a,b)=>diff(score(b),score(a))||diff(tie(b),tie(a))||a.name.localeCompare(b.name,'ja'));\n // 同順位（基準の値が同じなら同じ順位：1,1,3…）\n const scores=players.map(score).sort((a,b)=>diff(b,a)),firstAt=new Map();scores.forEach((v,i)=>{if(!firstAt.has(v))firstAt.set(v,i+1)});players.forEach(p=>p.place=firstAt.get(score(p)));\n $('#caption').textContent=Number($('#fromSeason').value)>Number($('#toSeason').value)?'開始期間が終了期間より後です。期間を選び直してください。':`該当 ${players.length} 人。名前を押すと、環境ごとの記録を表示します。`;\n $('#ranking tbody').innerHTML=players.length?players.slice(0,limit).map(p=>`<tr><td class=\"order\">${p.place}</td><td class=\"player-cell\"><button class=\"name\" type=\"button\" data-key=\"${escapeHTML(encodeURIComponent(p.key))}\">${escapeHTML(p.name)}</button></td>${cols.map(m=>`<td class=\"num${m===primary?' primary':''}\" data-label=\"${escapeHTML(m[1])}\">${escapeHTML(m[2](p))}</td>`).join('')}<td class=\"full-periods\" data-label=\"全ビヨ達成環境\">${escapeHTML(p.fullPeriods.join('、')||'—')}</td></tr>`).join(''):'<tr><td class=\"empty\" colspan=\"11\">該当するプレイヤーがいません。</td></tr>';\n const rest=players.length-limit;$('#more').hidden=rest<=0;$('#more').textContent=`さらに${Math.min(PAGE,rest)}人を表示（残り${rest}人）`;\n const selected=players.find(p=>p.key===active);\n if(!selected){$('#details').hidden=true}else{const p=selected;$('#details').hidden=false;$('#detailTitle').textContent=p.name+' の記録';\n  $('#detailStats').innerHTML=[`ビヨンド ${p.count}回`,`全ビヨ ${p.fullPeriods.length}回`,`最高CR ${p.max}`,`最高順位 ${rankText(p.bestRank)}`,`${n}位以内 ${p.rankHits}回`,`CR${x}以上 ${p.crHits}回`,`両方 ${p.bothHits}回`].map(t=>`<span>${escapeHTML(t)}</span>`).join('');\n  $('#fullBeyondPeriods').textContent='全ビヨ達成：'+(p.fullPeriods.map(s=>environmentOf(s)+' '+periodOf(s)).join('、')||'なし');\n  $('#detailRows').innerHTML=p.rows.slice().sort((a,b)=>SEASON_ORDER.indexOf(a.season)-SEASON_ORDER.indexOf(b.season)||CLASS_ORDER.indexOf(a.className)-CLASS_ORDER.indexOf(b.className)).map(r=>{const rh=rankHit(r,n),ch=r.cr>=x;return `<tr><td>${escapeHTML(environmentOf(r.season))}</td><td>${periodOf(r.season)}</td><td>${escapeHTML(r.className)}${r.rawName?`<span class=\"raw\">表記：${escapeHTML(r.rawName)}</span>`:''}</td><td class=\"num\">${r.cr}</td><td class=\"num\">${rankText(r.rank)}</td><td>${rh&&ch?'両方':rh?'順位のみ':ch?'CRのみ':'—'}</td></tr>`}).join('')}\n const averages=new Map();for(const r of rows){const k=r.season+'\\u001f'+r.className,v=averages.get(k)||{season:r.season,cls:r.className,count:0,sum:0,max:0};v.count++;v.sum+=r.cr;v.max=Math.max(v.max,r.cr);averages.set(k,v)}\n const byPeriod=(a,b)=>SEASON_ORDER.indexOf(a.season)-SEASON_ORDER.indexOf(b.season)||CLASS_ORDER.indexOf(a.cls)-CLASS_ORDER.indexOf(b.cls),averageSort=$('#averageSort').value;\n const averageRows=[...averages.values()].sort((a,b)=>averageSort==='average'?(b.sum/b.count-a.sum/a.count||byPeriod(a,b)):averageSort==='count'?(b.count-a.count||byPeriod(a,b)):byPeriod(a,b));\n $('#averages tbody').innerHTML=averageRows.map(v=>`<tr><td>${escapeHTML(environmentOf(v.season))}</td><td>${periodOf(v.season)}</td><td>${escapeHTML(v.cls)}</td><td class=\"num\">${v.count}</td><td class=\"num primary\">${(v.sum/v.count).toFixed(1)}</td><td class=\"num\">${v.max}</td></tr>`).join('')||'<tr><td class=\"empty\" colspan=\"6\">対象の記録がありません。</td></tr>';\n syncSortChips(n,x);\n document.querySelectorAll('#details table,#averages').forEach(t=>{const labels=[...t.querySelectorAll('th')].map(h=>h.textContent);t.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>td.dataset.label=labels[i]||''))});\n renderAverages(rows);\n renderScore();\n saveURL();\n}\nfor(const id of Object.values(PARAMS))$('#'+id).addEventListener('input',()=>{limit=PAGE;render()});\n$('#more').addEventListener('click',()=>{limit+=PAGE;render()});\n$('#ranking').addEventListener('click',e=>{const b=e.target.closest('[data-key]');if(!b)return;active=decodeURIComponent(b.dataset.key);render();$('#details').scrollIntoView({block:'nearest',behavior:'smooth'})});\n// ===== 総合スコア（式はシャドラボ準拠） =====\nconst MODELS={\n relax:{label:'緩和モデル',desc:'順位差を緩やかに評価（上位偏重を軽減）',formula:'100 ÷ 順位^0.3',f:r=>100/Math.pow(r,0.3)},\n inverse:{label:'逆数モデル',desc:'順位に反比例。1位と2位の差が最も大きいシビアな評価',formula:'100 ÷ 順位',f:r=>100/r},\n log:{label:'対数モデル',desc:'順位が上がるほど点数の上がり幅が増える（バランス型）',formula:'(log10(101) − log10(順位)) × 50',f:r=>Math.max(0,(Math.log10(101)-Math.log10(r))*50)}\n};\nconst RANK_CAP=100; // 101位以下は100位として計算\nfunction scoreTotals(rows,model){const f=MODELS[model].f,m=new Map();for(const r of achievementRows(rows)){if(!Number.isInteger(r.rank)||r.rank<1)continue;const k=pkey(r);let a=m.get(k);if(!a){a={key:k,name:r.name,search:new Set(),separated:!!r.separated,score:0,count:0,crSum:0,max:0};m.set(k,a)}a.search.add(norm(r.name));if(r.rawName)a.search.add(norm(r.rawName));a.score+=f(Math.min(r.rank,RANK_CAP));a.count++;a.crSum+=r.cr;a.max=Math.max(a.max,r.cr)}return m}\nfunction renderScore(){\n const model=MODELS[$('#model').value]?$('#model').value:'relax',M=MODELS[model];\n $('#modelbar').innerHTML=Object.entries(MODELS).map(([k,v])=>`<button type=\"button\" class=\"chip\" data-model=\"${k}\" aria-pressed=\"${k===model}\">${v.label}</button>`).join('');\n $('#modelNote').innerHTML=`<b style=\"color:var(--gold)\">${escapeHTML(M.desc)}</b>　計算式：<code>${escapeHTML(M.formula)}</code>`;\n const from=Number($('#fromSeason').value),to=Number($('#toSeason').value),c=$('#classFilter').value;\n const inRange=(lo,hi)=>DATA.filter(r=>{const i=SEASON_ORDER.indexOf(r.season);return i>=lo&&i<=hi&&(!c||r.className===c)});\n const now=scoreTotals(inRange(from,to),model),prev=to>from?scoreTotals(inRange(from,to-1),model):null;\n let list=[...now.values()].sort((a,b)=>b.score-a.score||b.max-a.max||a.name.localeCompare(b.name,'ja'));\n list.forEach((p,i)=>{p.place=i>0&&Math.abs(p.score-list[i-1].score)<1e-9?list[i-1].place:i+1;p.delta=p.score-(prev?.get(p.key)?.score||0)});\n const q=norm($('#search').value.trim());const shown=q?list.filter(p=>[...p.search].some(s=>s.includes(q))):list;\n $('#scoreCaption').textContent=from>to?'':`${list.length}人を集計${prev?`。前回比は「${SEASON_ORDER[to].replace(' ','')}」で増えた点数`:'。前回比は期間を2つ以上選ぶと表示'}`;\n $('#scoreTable tbody').innerHTML=shown.length?shown.slice(0,300).map(p=>`<tr class=\"${p.place<=3?'p'+p.place:''}\"><td>${p.place}</td><td class=\"player-cell\"><button class=\"name\" type=\"button\" data-key=\"${escapeHTML(encodeURIComponent(p.key))}\">${escapeHTML(p.name)}</button></td><td class=\"num primary\">${p.score.toFixed(2)}</td><td class=\"num ${prev&&p.delta>0.005?'up':'flat'}\">${prev?'+'+p.delta.toFixed(2):'—'}</td><td class=\"num\">${p.count}</td><td class=\"num\">${p.crSum.toLocaleString('ja-JP')}</td><td class=\"num\">${p.max}</td></tr>`).join('')+(shown.length>300?`<tr><td class=\"empty\" colspan=\"7\">上位300人まで表示しています。名前で検索すると全員を探せます。</td></tr>`:''):'<tr><td class=\"empty\" colspan=\"7\">該当するプレイヤーがいません。</td></tr>';\n $('#howto').innerHTML=`<p>到達記録1件ごとに、その枠（期間×クラス）でのゲーム内順位から点数を出し、全部を合計します。同じCRで同順位の人は同じ点数です。</p>\n<ul><li>緩和モデル：<code>100 ÷ 順位^0.3</code></li><li>逆数モデル：<code>100 ÷ 順位</code></li><li>対数モデル：<code>(log10(101) − log10(順位)) × 50</code></li></ul>\n<p>選択したモデルで記録ごとの点数を計算します。</p>\n<p>アンリミは100位を超える枠もあるため、101位以下は100位として計算します（どのモデルでも共通）。</p>`;\n}\n$('#modelbar').addEventListener('click',e=>{const b=e.target.closest('[data-model]');if(b){$('#model').value=b.dataset.model;render()}});\n$('#scoreTable').addEventListener('click',e=>{const b=e.target.closest('[data-key]');if(!b)return;$('#matchFilter').value='all';active=decodeURIComponent(b.dataset.key);render();$('#details').scrollIntoView({block:'nearest',behavior:'smooth'})});\n// ===== 平均CRのグラフ =====\nconst SHORT_CLASS={'エルフ':'エルフ','ロイヤル':'ロイ','ウィッチ':'ウィ','ドラゴン':'ドラ','ナイトメア':'ナイト','ビショップ':'ビショ','ネメシス':'ネメ'};\nconst shortSeason=s=>environmentOf(s).replace(/[・ ].*$/,'').slice(0,3)+periodOf(s).slice(0,1);\nconst lerp=(a,b,t)=>a+(b-a)*t;\nconst DARK=()=>matchMedia('(prefers-color-scheme: dark)').matches;\nconst CLASS_VAR={'エルフ':'var(--elf)','ロイヤル':'var(--royal)','ウィッチ':'var(--witch)','ドラゴン':'var(--dragon)','ナイトメア':'var(--nightmare)','ビショップ':'var(--bishop)','ネメシス':'var(--nemesis)'};\nconst CLASSIC=()=>document.documentElement.classList.contains('classic');\nfunction heatColor(t){const stops=CLASSIC()?[[22,55,74],[63,154,156],[164,244,239]]:DARK()?[[38,34,51],[47,111,128],[79,184,207]]:[[235,233,241],[124,184,196],[46,125,143]],u=t<.5?t*2:(t-.5)*2,[a,b]=t<.5?[stops[0],stops[1]]:[stops[1],stops[2]];return `rgb(${a.map((v,i)=>Math.round(lerp(v,b[i],u))).join(',')})`}\nmatchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{try{render()}catch(e){}});\nfunction renderAverages(rows){\n const from=Number($('#fromSeason').value),to=Number($('#toSeason').value),c=$('#classFilter').value;\n const classes=c?[c]:CLASS_ORDER,seasons=SEASON_ORDER.slice(from,to+1);\n // 横棒：クラス別（期間をまとめて）\n const byClass=classes.map(cls=>{const rs=rows.filter(r=>r.className===cls);return {cls,count:rs.length,avg:rs.length?rs.reduce((t,r)=>t+r.cr,0)/rs.length:null,max:rs.length?Math.max(...rs.map(r=>r.cr)):null}}).filter(v=>v.count).sort((a,b)=>b.avg-a.avg);\n const hi=Math.ceil((Math.max(1855,...byClass.map(v=>v.avg))-1850)/10)*10+1850;\n $('#barsSub').textContent=seasons.length?`${seasons.length===1?SEASON_ORDER[from]:SEASON_ORDER[from]+' 〜 '+SEASON_ORDER[to]} の到達者。棒はビヨンドライン（CR1850）からの高さ。`:'';\n $('#avgBars').innerHTML=byClass.length?byClass.map(v=>{const tip=`<b>${escapeHTML(v.cls)}</b><br>平均CR ${v.avg.toFixed(1)}<br>到達 延べ${v.count}件<br>最高CR ${v.max}`;return `<div class=\"bar\" style=\"--k:${CLASS_VAR[v.cls]||'var(--t2)'}\" tabindex=\"0\" data-tip=\"${escapeHTML(tip)}\" aria-label=\"${escapeHTML(v.cls)} 平均CR ${v.avg.toFixed(1)}、延べ${v.count}件\"><span><span class=\"long\">${escapeHTML(v.cls)}</span><span class=\"short\">${escapeHTML(SHORT_CLASS[v.cls]||v.cls)}</span></span><span class=\"track\"><span class=\"fill\" style=\"width:${Math.max(1.5,(v.avg-1850)/(hi-1850)*100)}%\"></span></span><span class=\"v\">${v.avg.toFixed(1)}<small>延べ${v.count}件</small></span></div>`}).join('')+`<div class=\"axis\"><span></span><span class=\"ticks\">${(()=>{const narrow=innerWidth<650,step=hi-1850<=30&&!narrow?5:hi-1850<=60?10:20,out=[];for(let t=1850;t<=hi;t+=step)out.push(`<span style=\"left:${(t-1850)/(hi-1850)*100}%\">${t}</span>`);return out.join('')})()}</span><span></span></div>`:'<p class=\"empty\">対象の記録がありません。</p>';\n // ヒートマップ：期間 × クラス\n const cell=new Map();for(const r of rows){const k=r.season+'\\u001f'+r.className,v=cell.get(k)||{n:0,sum:0,max:0};v.n++;v.sum+=r.cr;v.max=Math.max(v.max,r.cr);cell.set(k,v)}\n const avgs=[...cell.values()].map(v=>v.sum/v.n),lo=Math.min(...avgs),top=Math.max(...avgs),span=top-lo||1;\n $('#scaleLo').textContent=avgs.length?lo.toFixed(1):'';$('#scaleHi').textContent=avgs.length?top.toFixed(1):'';\n $('#heat').style.gridTemplateColumns=`minmax(48px,auto) repeat(${classes.length},minmax(0,1fr))`;\n $('#heat').innerHTML=seasons.length&&avgs.length?'<span></span>'+classes.map(cls=>`<span class=\"hd\" style=\"--k:${CLASS_VAR[cls]||'var(--muted)'}\"><span class=\"long\">${escapeHTML(cls)}</span><span class=\"short\">${escapeHTML(SHORT_CLASS[cls]||cls)}</span></span>`).join('')+seasons.map(se=>`<span class=\"rl\"><span class=\"long\">${escapeHTML(environmentOf(se))} ${periodOf(se)}</span><span class=\"short\">${escapeHTML(shortSeason(se))}</span></span>`+classes.map(cls=>{const v=cell.get(se+'\\u001f'+cls);if(!v)return '<span class=\"cell none\" aria-label=\"記録なし\">—</span>';const a=v.sum/v.n,t=(a-lo)/span;const tip=`<b>${escapeHTML(environmentOf(se))} ${periodOf(se)}・${escapeHTML(cls)}</b><br>平均CR ${a.toFixed(1)}<br>到達 ${v.n}人<br>最高CR ${v.max}`;return `<span class=\"cell\" tabindex=\"0\" style=\"background:${heatColor(t)};color:${DARK()?(t>.55?'#121019':'#efedf5'):(t>.55?'#ffffff':'#17151f')}\" data-tip=\"${escapeHTML(tip)}\" aria-label=\"${escapeHTML(se)} ${escapeHTML(cls)} 平均CR ${a.toFixed(1)}、${v.n}人\">${Math.round(a)}</span>`}).join('')).join(''):'<p class=\"empty\">対象の記録がありません。</p>';\n}\n// ツールチップ（マウス・タップ・キーボード共通）\n(()=>{const tip=$('#tip');let pinned=null;\n const show=(el,x,y)=>{tip.innerHTML=el.dataset.tip;tip.hidden=false;const w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.min(innerWidth-w-8,Math.max(8,x+12))+'px';tip.style.top=(y-h-12<8?y+16:y-h-12)+'px'};\n const hide=()=>{tip.hidden=true;pinned=null};\n document.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const el=e.target.closest('[data-tip]');el?show(el,e.clientX,e.clientY):pinned||hide()});\n document.addEventListener('click',e=>{const el=e.target.closest('[data-tip]');if(el&&pinned!==el){const r=el.getBoundingClientRect();show(el,r.left+r.width/2,r.top);pinned=el}else hide()});\n document.addEventListener('focusin',e=>{const el=e.target.closest('[data-tip]');if(el){const r=el.getBoundingClientRect();show(el,r.left+r.width/2,r.top)}});\n document.addEventListener('focusout',hide);addEventListener('scroll',hide,{passive:true});})();\nfunction setSort(key){$('#sort').value=key;limit=PAGE;render()}\n$('#sortbar').addEventListener('click',e=>{const b=e.target.closest('[data-sort]');if(b)setSort(b.dataset.sort)});\n$('#ranking thead').addEventListener('click',e=>{const b=e.target.closest('[data-sort]');if(b)setSort(b.dataset.sort)});\n$('#closeDetails').addEventListener('click',()=>{active='';$('#details').hidden=true;saveURL()});\n$('#copyLink').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);$('#copyNote').textContent='コピーしました'}catch(e){$('#copyNote').textContent='コピーできませんでした。アドレスバーのURLを使ってください'}setTimeout(()=>$('#copyNote').textContent='',2500)});\ninitSortChips();loadURL();render();\n(()=>{const box=$('#suspects'),list=SUSPECT.map(n=>[n,DATA.filter(r=>r.name===n).sort((a,b)=>SEASON_ORDER.indexOf(a.season)-SEASON_ORDER.indexOf(b.season)||CLASS_ORDER.indexOf(a.className)-CLASS_ORDER.indexOf(b.className)||a.rank-b.rank)]).filter(([,rs])=>rs.length>1);\n if(!list.length){$('#suspectBox').hidden=true;return}\n box.innerHTML=list.map(([n,rs])=>`<p><b>${escapeHTML(n)}</b>（${rs.length}件）：${rs.map(r=>`${escapeHTML(shortSeason(r.season))} ${escapeHTML(SHORT_CLASS[r.className]||r.className)} ${r.rank}位 CR${r.cr}`).join('、')}</p>`).join('');})();\napplyTheme(CLASSIC());\n$('#themeToggle').addEventListener('click',()=>{const c=!CLASSIC();applyTheme(c);try{localStorage.setItem('design',c?'classic':'modern')}catch(e){}render()});\n// ページ内ナビ：今いるセクションを光らせる＋先頭へボタン\n(()=>{const links=[...document.querySelectorAll('.jump a')],heads=links.map(a=>document.querySelector(a.getAttribute('href')));\n const update=()=>{let cur=0;heads.forEach((h,i)=>{if(h.getBoundingClientRect().top<120)cur=i});links.forEach((a,i)=>a.classList.toggle('on',i===cur));$('#toTop').hidden=scrollY<600};\n addEventListener('scroll',update,{passive:true});update();\n let rw=innerWidth;addEventListener('resize',()=>{if((rw<650)!==(innerWidth<650)){rw=innerWidth;render()}});\n $('#toTop').addEventListener('click',()=>scrollTo({top:0}));})();\n</script></body></html>\n";